insert into public.seo_landing_pages (slug,title,heading,intro,body,meta_title,meta_description,public_link_label,public_link_description,canonical_path,page_type,listing_type_slug,city,filters,hero_media_id,og_image,keywords,status,published_at,noindex,sort_order,show_in_footer,show_on_home,show_on_buy_sell) select slug,title,heading,intro,body,meta_title,meta_description,public_link_label,public_link_description,canonical_path,page_type,listing_type_slug,city,filters,hero_media_id,og_image,keywords,status,published_at,noindex,sort_order,show_in_footer,show_on_home,show_on_buy_sell from jsonb_populate_recordset(null::public.seo_landing_pages,'[{"slug":"real-estate-lahore","title":"Real Estate Services in Lahore","heading":"Real estate services in Lahore by Estate Brothers","intro":"Estate Brothers supports buyers, sellers and investors with Lahore property comparisons, payment-plan guidance and client coordination from 44-A DHA Phase 6.","body":"Estate Brothers helps clients compare residential and commercial property opportunities across Lahore. Its main office is at 44-A DHA Phase 6, where clients can arrange private meetings, discuss their requirements and review property options with the team.\n\nFor a buyer, a useful comparison starts with the property type, location and size. The current listing collection covers Etihad Town Phase IV, Al Ghani Garden Phase 7, Safari Garden and Green Palms Housing Lahore. Each project has its own payment schedule and conditions; an entry price should be read alongside the booking amount, instalments, possession payment and any separate development charges.\n\nSellers and investors can contact Estate Brothers for property services, investment guidance, documentation support and client representation. Explain your preferred location, budget and time frame so the team can help narrow the options. DHA Lahore advisory is available even when a particular DHA plot is not in the public inventory.\n\nThe listings below provide the published price and terms for comparison. Confirm present availability and the applicable charges with the team before making a commitment. Call +923252222330 or email estatebrothers786@gmail.com to arrange a conversation.","meta_title":"Real Estate Services in Lahore | Estate Brothers","meta_description":"Explore Lahore real estate with Estate Brothers: plot comparisons, payment-plan guidance and property services from the main office at 44-A DHA Phase 6.","public_link_label":"Real estate Lahore","public_link_description":"Lahore property services, project comparisons and guidance from our DHA Phase 6 team.","canonical_path":"/real-estate-lahore","page_type":"area","listing_type_slug":"plot","city":"Lahore","filters":{},"hero_media_id":"10000000-0000-0000-0000-000000000001","og_image":"/og-default.jpg","keywords":["Real Estate Services in Lahore","Lahore plots","Estate Brothers"],"status":"published","published_at":"2026-05-24T00:00:00Z","noindex":false,"sort_order":20,"show_in_footer":true,"show_on_home":true,"show_on_buy_sell":true},{"slug":"properties-in-lahore","title":"Properties in Lahore","heading":"Properties in Lahore for buyers and investors","intro":"Compare residential and commercial plots in Lahore by project, size, asking price and payment terms, with direct support from the Estate Brothers team.","body":"Start your Lahore property search by deciding whether you need a residential plot or a commercial opportunity, the size you want and the payment schedule that suits your plans. Estate Brothers brings these facts together in its property listings so you can compare options before speaking with the team.\n\nThe original inventory includes Etihad Town Phase IV residential plots in 5, 10, 20 and 40 Marla sizes; Al Ghani Garden Phase 7 residential and commercial options; Safari Garden plots in 3, 5, 8 and 10 Marla sizes; and Green Palms Housing Lahore residential and commercial payment plans. Use the full Buy/Sell table to compare all published options.\n\nPayment plans are not interchangeable. Review the initial payment, monthly instalments, balloon or annual payments, possession amount and any booking or processing fees. Several listings quote the cost of land separately from development charges. Corner, park-facing and boulevard categories may also carry premiums where the individual listing states them.\n\nThe collection currently focuses on plots. Contact Estate Brothers about house requirements or an option that is not shown; do not assume a particular property is available just because a project is represented. The team can confirm the current asking price, terms and availability on +923252222330 from its 44-A DHA Phase 6 Lahore office.","meta_title":"Properties in Lahore: Plots & Payment Plans | Estate Brothers","meta_description":"Compare residential and commercial plots in Lahore, including Etihad Town, Al Ghani Garden, Safari Garden and Green Palms, with Estate Brothers.","public_link_label":"Properties in Lahore","public_link_description":"Compare Lahore residential and commercial plots, sizes, prices and payment plans.","canonical_path":"/properties-in-lahore","page_type":"area","listing_type_slug":"plot","city":"Lahore","filters":{},"hero_media_id":"10000000-0000-0000-0000-000000000001","og_image":"/og-default.jpg","keywords":["Properties in Lahore","Lahore plots","Estate Brothers"],"status":"published","published_at":"2026-05-24T00:00:00Z","noindex":false,"sort_order":30,"show_in_footer":true,"show_on_home":true,"show_on_buy_sell":true}]'::jsonb) on conflict (slug) do update set title=excluded.title,heading=excluded.heading,intro=excluded.intro,body=excluded.body,meta_title=excluded.meta_title,meta_description=excluded.meta_description,public_link_label=excluded.public_link_label,public_link_description=excluded.public_link_description,canonical_path=excluded.canonical_path,page_type=excluded.page_type,listing_type_slug=excluded.listing_type_slug,city=excluded.city,filters=excluded.filters,hero_media_id=excluded.hero_media_id,og_image=excluded.og_image,keywords=excluded.keywords,status=excluded.status,published_at=excluded.published_at,noindex=excluded.noindex,sort_order=excluded.sort_order,show_in_footer=excluded.show_in_footer,show_on_home=excluded.show_on_home,show_on_buy_sell=excluded.show_on_buy_sell;

